const body = $json.body ?? $json;
const request = String(body.request ?? body.message ?? '');
const customerId = String(body.customer_id ?? 'CUST-DEMO');
const orderId = String(body.order_id ?? 'ORD-DEMO');
return [{
  json: {
    request,
    customer_id: customerId,
    order_id: orderId,
    received_at: new Date().toISOString(),
    source: body.source ?? 'webhook'
  }
}];

