const raw = $json.choices?.[0]?.message?.content ?? '{}';
let decision;
try { decision = JSON.parse(raw); } catch (e) {
  decision = {
    intent: 'unknown',
    urgency: 'normal',
    entities: {},
    decision: 'HUMAN_APPROVAL',
    confidence: 0,
    reason: 'AI response could not be parsed safely.',
    customer_message: 'Your request has been sent for human review.'
  };
}
return [{ json: { ...$node['Normalize Request'].json, ...decision } }];

return [{
  json: {
    status: 'AUTO_RESOLVED',
    action: 'REFUND_CREATED',
    refund_id: 'RF-' + Date.now(),
    customer_id: $json.customer_id,
    order_id: $json.order_id,
    reason: $json.reason,
    message: $json.customer_message,
    audit: {
      agent_decision: $json.decision,
      confidence: $json.confidence,
      timestamp: new Date().toISOString()
    }
  }
}];

return [{
